<?php
function bizQtyGrid(array $products,array $items,bool $readonly=false,?array $units=null,array $amounts=[]): void { ?>
<?php if($units!==null): ?><p class="hint">수량 · 납품 전체 금액 (할인·HST 전)</p><?php endif ?>
<div class="biz-order-grid" data-biz-qty-grid <?=$units!==null?'data-biz-priced-grid':''?>><?php foreach(bizCategories() as $key=>$label):$group=array_filter($products,fn($p)=>$p['category']===$key);if(!$group)continue; ?><section class="biz-quantity-category"><h3><?=$label?> <span><span class="biz-category-total" data-biz-total>0개</span> <?php if($units!==null): ?><span data-biz-amount></span><?php endif ?></span></h3><div class="biz-quantity-rows"><?php foreach($group as $p): ?><label data-biz-product="<?=$p['id']?>"><span><?=e(bizKo($p))?></span><input aria-label="<?=e(bizKo($p))?> 수량" data-biz-qty name="qty[<?=$p['id']?>]" type="number" inputmode="numeric" min="0" max="10000" value="<?=(int)($items[$p['id']]??0)?>" <?=$readonly?'readonly':''?>><?php if($units!==null): ?><input data-biz-amount-input data-default-unit="<?=isset($amounts[$p['id']])&&($items[$p['id']]??0)>0?$amounts[$p['id']]/100/$items[$p['id']]:($units[$p['id']]??0)/100?>" aria-label="<?=e(bizKo($p))?> 납품 전체 금액" name="amount[<?=$p['id']?>]" type="number" min="0" max="999999.99" step=".01" placeholder="전체 금액" value="<?=number_format((($items[$p['id']]??0)>0?($amounts[$p['id']]??(($units[$p['id']]??0)*$items[$p['id']])):0)/100,2,'.','')?>" <?=$readonly?'readonly':''?>><?php endif ?></label><?php endforeach ?></div></section><?php endforeach ?><p class="biz-quantity-grand-total">총 주문 수량 <strong data-biz-grand-total>0개</strong> <?php if($units!==null): ?><span>· 금액 (할인·HST 전) <strong data-biz-grand-amount></strong></span><?php endif ?></p></div>
<?php }
